import json
with open('./ui_capture_output/layout.json','r', encoding='utf-8') as f:
    data = json.load(f)
# Dump all keys at root level
if isinstance(data, dict):
    print('Root keys:', list(data.keys())[:20])
elif isinstance(data, list):
    print('Root is list, len:', len(data))

def explore(node, depth=0, max_d=3):
    if depth > max_d:
        return ''
    if isinstance(node, dict):
        t = node.get('type', node.get('tag', node.get('class', '')))
        keys = list(node.keys())
        extra = ''
        if 'text' in node: extra += f\" text='{str(node[\"text\"])[:20]}'\"
        if 'value' in node: extra += f\" value='{str(node[\"value\"])[:20]}'\"
        if 'label' in node: extra += f\" label='{str(node[\"label\"])[:20]}'\"
        print(f\"{'  '*depth}[D] type={t} keys={keys[:10]}...{extra}\")
        for k in keys:
            v = node[k]
            if isinstance(v, (dict, list)):
                explore(v, depth+1, max_d)
        return
    if isinstance(node, list):
        for i, item in enumerate(node[:5]):
            explore(item, depth, max_d)

explore(data, 0, 4)
" 2>&1
